// Normalize items from both Apify sources into a common schema
// and deduplicate by (company + title) key

const seen = new Set();
const normalized = [];

for (const item of $input.all()) {
  const raw = item.json;

  // Handle both array responses (dataset items) and single object responses
  const jobs = Array.isArray(raw) ? raw : [raw];

  for (const job of jobs) {
    // Skip empty or error items
    if (!job || typeof job !== 'object') continue;

    // Normalize field names across Hiring.cafe and LinkedIn schemas
    const title = (
      job.title ||
      job.jobTitle ||
      job.position ||
      job.name ||
      ''
    ).trim();

    const company = (
      job.company ||
      job.companyName ||
      job.employer ||
      job.organizationName ||
      ''
    ).trim();

    if (!title || !company) continue;

    // Deduplicate by lowercase company+title
    const dedupKey = `${company.toLowerCase()}::${title.toLowerCase()}`;
    if (seen.has(dedupKey)) continue;
    seen.add(dedupKey);

    const description = (
      job.description ||
      job.jobDescription ||
      job.descriptionHtml ||
      job.snippet ||
      ''
    ).replace(/<[^>]*>/g, ' ').trim().substring(0, 4000);

    const salary = (
      job.salary ||
      job.salaryRange ||
      job.compensation ||
      ''
    ).toString().trim();

    const applicationUrl = (
      job.applicationUrl ||
      job.applyUrl ||
      job.url ||
      job.jobUrl ||
      job.link ||
      ''
    ).trim();

    const source = job.source || 'unknown';

    normalized.push({
      json: {
        title,
        company,
        description,
        salary,
        applicationUrl,
        source,
        scrapedAt: new Date().toISOString()
      }
    });
  }
}

if (normalized.length === 0) {
  throw new Error('No jobs found after normalization. Check Apify actor IDs and that scrapes returned data.');
}

return normalized;

// Build the Claude API request body for each job
// The system prompt encodes Hersh's background for scoring

const SYSTEM_PROMPT = `You are an expert recruiter evaluating candidate-job fit for a senior fintech and AI product leader.

Candidate background:
- 12 years of product and program leadership at Goldman Sachs, Morgan Stanley, and Coinbase
- Deep expertise in fintech infrastructure, compliance technology, and regulatory systems
- Production experience with RAG systems, MCP agentic workflows, and n8n automation
- Columbia MBA
- Currently based in Washington DC metro area
- Target roles: Principal PM, Senior Director of Product, Lead PM, TPM at fintech or AI infrastructure companies
- Salary target: $250K+ base

Your task: Score this job posting 1–10 based on fit with the candidate above.

Return ONLY valid JSON in this exact schema (no markdown, no extra text):
{
  "score": <integer 1-10>,
  "fitReasons": ["<reason 1>", "<reason 2>", "<reason 3>"],
  "gaps": ["<gap 1>", "<gap 2>"],
  "summary": "<one sentence summary of fit>"
}`;

const job = $json;

const userMessage = `Job Title: ${job.title}
Company: ${job.company}
Salary: ${job.salary || 'Not specified'}
Source: ${job.source}

Job Description:
${job.description}`;

const requestBody = {
  model: 'claude-sonnet-4-20250514',
  max_tokens: 1024,
  system: SYSTEM_PROMPT,
  messages: [
    {
      role: 'user',
      content: userMessage
    }
  ]
};

return [
  {
    json: {
      ...job,
      _claudeRequestBody: JSON.stringify(requestBody)
    }
  }
];

// Extract the score and fit details from Claude's response
// Merge back with the original job data stored in the response headers trick
// Note: The HTTP Request node replaces $json with the API response,
// so we need to parse what Claude returned

const apiResponse = $json;

// Default values in case parsing fails
let score = 0;
let fitReasons = [];
let gaps = [];
let summary = 'Scoring failed';
let parseError = null;

try {
  if (apiResponse.error) {
    throw new Error(`Claude API error: ${apiResponse.error.message || JSON.stringify(apiResponse.error)}`);
  }

  const content = apiResponse?.content?.[0]?.text;
  if (!content) {
    throw new Error('No content in Claude response');
  }

  // Strip markdown code fences if Claude wrapped the JSON
  const cleaned = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  const parsed = JSON.parse(cleaned);

  score = parseInt(parsed.score, 10) || 0;
  fitReasons = Array.isArray(parsed.fitReasons) ? parsed.fitReasons : [];
  gaps = Array.isArray(parsed.gaps) ? parsed.gaps : [];
  summary = parsed.summary || '';

} catch (err) {
  parseError = err.message;
}

// We lose the original job data because the HTTP Request node replaced $json.
// The job fields are NOT available here. This is handled by using the
// StickyNote pattern: pass job data through a separate field in the request.
// Since we embedded job data in _claudeRequestBody, re-parse it here.
let jobData = {};
try {
  // The input to the HTTP node had job fields; they are now gone.
  // We store them in the usage metadata comment of the request body.
  // Alternative approach: use n8n's $node reference.
  // Best approach: retrieve from previous node using $node["Prepare Claude Scoring Request"].json
  const prevNode = $node["Prepare Claude Scoring Request"].json;
  jobData = {
    title: prevNode.title,
    company: prevNode.company,
    description: prevNode.description,
    salary: prevNode.salary,
    applicationUrl: prevNode.applicationUrl,
    source: prevNode.source,
    scrapedAt: prevNode.scrapedAt
  };
} catch (err) {
  // If node reference fails, proceed with what we have
}

return [
  {
    json: {
      ...jobData,
      score,
      fitReasons,
      gaps,
      summary,
      parseError,
      scoredAt: new Date().toISOString(),
      claudeTokensUsed: apiResponse?.usage?.input_tokens + apiResponse?.usage?.output_tokens || 0
    }
  }
];
